def astype_builder(df):
    """Compute new partition frame with dtypes updated."""
    try:
        return df.astype(
            {k: v for k, v in col_dtypes.items() if k in df}, errors=errors
        )
    except ValueError:
        # This can happen when a partition's data is backed by a
        # read-only buffer (e.g. coming from the Ray object store) and
        # the cast requires a writable array. Copy the frame and retry.
        return df.copy().astype(
            {k: v for k, v in col_dtypes.items() if k in df}, errors=errors
        )
